<template>
  <div class="page-container">
    <el-card shadow="never" class="header-card">
      <div class="header"><div><h2>成果、知识产权与获奖申报</h2><p>补充论文/著作之外的成果类型，记录知识产权申请到授权的状态、代理机构和缴费提醒，并完成获奖申报评审。</p></div><el-button :icon="Refresh" :loading="loading" @click="refresh">刷新</el-button></div>
    </el-card>
    <el-card shadow="never" class="content-card">
      <el-tabs v-model="tab" @tab-change="onTabChange">
        <el-tab-pane label="其他成果" name="extensions">
          <div class="toolbar"><el-select v-model="extensionFilter" clearable placeholder="成果类别" style="width:150px"><el-option v-for="x in extensionTypes" :key="x" :label="x" :value="x" /></el-select><el-button type="primary" @click="openExtension()">登记成果</el-button></div>
          <el-table v-loading="loadingExtensions" :data="extensions" border stripe><el-table-column prop="成果类别" label="成果类别" width="130"/><el-table-column prop="成果名称" label="成果名称" min-width="260"/><el-table-column prop="年度" label="年度" width="80"/><el-table-column prop="负责人姓名" label="负责人" width="110"/><el-table-column prop="审核状态" label="审核状态" width="100"><template #default="{row}"><el-tag :type="auditType(row.审核状态)">{{ row.审核状态 }}</el-tag></template></el-table-column><el-table-column prop="成果摘要" label="摘要" min-width="250" show-overflow-tooltip/><el-table-column label="操作" width="150" fixed="right"><template #default="{row}"><el-button link type="primary" @click="openExtension(row)">编辑</el-button><el-button v-if="row.审核状态 === '待审核'" link type="success" @click="reviewExtension(row,'已通过')">通过</el-button></template></el-table-column></el-table>
          <el-empty v-if="!loadingExtensions && !extensions.length" description="暂无其他成果记录"/>
        </el-tab-pane>
        <el-tab-pane label="知识产权" name="ip">
          <div class="toolbar"><el-select v-model="ipFilter" clearable placeholder="知识产权类型" style="width:160px"><el-option v-for="x in ipTypes" :key="x" :label="x" :value="x" /></el-select><el-checkbox v-model="dueOnly">仅看60日内缴费</el-checkbox><el-button type="primary" @click="openIp()">登记知识产权</el-button></div>
          <el-table v-loading="loadingIp" :data="ips" border stripe><el-table-column prop="知识产权类型" label="类型" width="115"/><el-table-column prop="名称" label="名称" min-width="260"/><el-table-column prop="状态" label="当前状态" width="100"><template #default="{row}"><el-tag :type="ipStatusType(row.状态)">{{ row.状态 }}</el-tag></template></el-table-column><el-table-column prop="申请号" label="申请号" width="160"/><el-table-column prop="代理机构" label="代理机构" width="180" show-overflow-tooltip/><el-table-column prop="下次缴费日期" label="下次缴费" width="125"/><el-table-column prop="待缴费提醒数" label="缴费提醒" width="95"/><el-table-column label="操作" width="170" fixed="right"><template #default="{row}"><el-button link type="primary" @click="openIp(row)">编辑</el-button><el-button link type="warning" @click="openIpEvent(row)">登记事件</el-button></template></el-table-column></el-table>
          <el-empty v-if="!loadingIp && !ips.length" description="暂无知识产权记录"/>
        </el-tab-pane>
        <el-tab-pane label="获奖申报批次" name="batches">
          <div class="toolbar"><el-button type="primary" @click="openBatch()">新建申报批次</el-button></div>
          <el-table v-loading="loadingBatches" :data="batches" border stripe><el-table-column prop="计划年度" label="年度" width="80"/><el-table-column prop="批次名称" label="批次名称" min-width="220"/><el-table-column prop="获奖类别" label="获奖类别" width="150"/><el-table-column prop="申报开始日期" label="开始日期" width="120"/><el-table-column prop="申报截止日期" label="截止日期" width="120"/><el-table-column prop="申报数" label="申报数" width="80"/><el-table-column prop="状态" label="状态" width="90"><template #default="{row}"><el-tag :type="row.状态 === '发布' ? 'success' : row.状态 === '关闭' ? 'info' : 'warning'">{{ row.状态 }}</el-tag></template></el-table-column><el-table-column label="操作" width="90"><template #default="{row}"><el-button link type="primary" @click="openBatch(row)">编辑</el-button></template></el-table-column></el-table>
        </el-tab-pane>
        <el-tab-pane label="获奖申报与评审" name="applications">
          <div class="toolbar"><el-select v-model="applicationBatch" clearable placeholder="按批次筛选" style="width:220px"><el-option v-for="b in batches" :key="b.编号" :label="b.批次名称" :value="b.编号"/></el-select><el-button type="primary" @click="openApplication()">新建申报</el-button></div>
          <el-table v-loading="loadingApplications" :data="applications" border stripe><el-table-column prop="批次名称" label="申报批次" min-width="180"/><el-table-column prop="申报名称" label="申报名称" min-width="240"/><el-table-column prop="申报人姓名" label="申报人" width="110"/><el-table-column prop="拟申报级别" label="拟申报级别" width="130"/><el-table-column prop="状态" label="状态" width="100"><template #default="{row}"><el-tag :type="applicationType(row.状态)">{{ row.状态 }}</el-tag></template></el-table-column><el-table-column prop="平均评分" label="平均评分" width="100"/><el-table-column label="操作" width="210" fixed="right"><template #default="{row}"><el-button v-if="row.状态 === '草稿'" link type="primary" @click="submitApplication(row)">提交</el-button><el-button link type="primary" @click="openApplication(row)">编辑</el-button><el-button v-if="row.状态 === '评审中'" link type="warning" @click="openReviews(row)">查看评审</el-button><el-button v-if="row.状态 === '拟推荐'" link type="success" @click="openCertify(row)">认定</el-button></template></el-table-column></el-table>
          <el-empty v-if="!loadingApplications && !applications.length" description="暂无获奖申报"/>
        </el-tab-pane>
      </el-tabs>
    </el-card>

    <el-dialog v-model="extensionDialog.visible" :title="extensionDialog.form.编号 ? '编辑成果' : '登记其他成果'" width="620px"><el-form :model="extensionDialog.form" label-width="100px"><el-form-item label="成果类别"><el-select v-model="extensionDialog.form.成果类别"><el-option v-for="x in extensionTypes" :key="x" :label="x" :value="x"/></el-select></el-form-item><el-form-item label="成果名称"><el-input v-model="extensionDialog.form.成果名称"/></el-form-item><el-form-item label="年度"><el-input-number v-model="extensionDialog.form.年度" :min="1900" :max="2200"/></el-form-item><el-form-item label="完成日期"><el-date-picker v-model="extensionDialog.form.完成日期" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="成果摘要"><el-input v-model="extensionDialog.form.成果摘要" type="textarea" :rows="3"/></el-form-item><el-form-item label="扩展字段(JSON)"><el-input v-model="extensionDialog.extra" placeholder='例如：{"出版社":"人民卫生出版社"}'/></el-form-item></el-form><template #footer><el-button @click="extensionDialog.visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveExtension">保存</el-button></template></el-dialog>

    <el-dialog v-model="ipDialog.visible" :title="ipDialog.form.编号 ? '编辑知识产权' : '登记知识产权'" width="700px"><el-form :model="ipDialog.form" label-width="105px"><el-form-item label="类型"><el-select v-model="ipDialog.form.知识产权类型"><el-option v-for="x in ipTypes" :key="x" :label="x" :value="x"/></el-select></el-form-item><el-form-item label="名称"><el-input v-model="ipDialog.form.名称"/></el-form-item><el-form-item label="状态"><el-select v-model="ipDialog.form.状态"><el-option v-for="x in ipStates" :key="x" :label="x" :value="x"/></el-select></el-form-item><el-form-item label="申请号"><el-input v-model="ipDialog.form.申请号"/></el-form-item><el-form-item label="申请日期"><el-date-picker v-model="ipDialog.form.申请日期" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="证书号"><el-input v-model="ipDialog.form.证书号"/></el-form-item><el-form-item label="授权日期"><el-date-picker v-model="ipDialog.form.授权日期" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="代理机构"><el-input v-model="ipDialog.form.代理机构"/></el-form-item><el-form-item label="下次缴费日期"><el-date-picker v-model="ipDialog.form.下次缴费日期" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="费用"><el-input-number v-model="ipDialog.form.总费用" :min="0"/><span class="inline-label">已缴</span><el-input-number v-model="ipDialog.form.已缴费用" :min="0"/></el-form-item><el-form-item label="摘要"><el-input v-model="ipDialog.form.摘要" type="textarea" :rows="2"/></el-form-item></el-form><template #footer><el-button @click="ipDialog.visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveIp">保存</el-button></template></el-dialog>

    <el-dialog v-model="ipEventDialog.visible" title="登记知识产权事件" width="560px"><el-form :model="ipEventDialog.form" label-width="100px"><el-form-item label="事件类型"><el-select v-model="ipEventDialog.form.事件类型"><el-option v-for="x in ipEvents" :key="x" :label="x" :value="x"/></el-select></el-form-item><el-form-item label="事件日期"><el-date-picker v-model="ipEventDialog.form.事件日期" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="金额"><el-input-number v-model="ipEventDialog.form.金额" :min="0"/></el-form-item><el-form-item label="下次缴费日期"><el-date-picker v-model="ipEventDialog.form.下次缴费日期" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="说明"><el-input v-model="ipEventDialog.form.事件说明" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="ipEventDialog.visible=false">取消</el-button><el-button type="primary" @click="saveIpEventForm">保存事件</el-button></template></el-dialog>

    <el-dialog v-model="batchDialog.visible" :title="batchDialog.form.编号 ? '编辑申报批次' : '新建申报批次'" width="680px"><el-form :model="batchDialog.form" label-width="110px"><el-form-item label="计划年度"><el-input-number v-model="batchDialog.form.计划年度" :min="1900" :max="2200"/></el-form-item><el-form-item label="批次名称"><el-input v-model="batchDialog.form.批次名称"/></el-form-item><el-form-item label="获奖类别"><el-input v-model="batchDialog.form.获奖类别"/></el-form-item><el-form-item label="申报日期"><el-date-picker v-model="batchDialog.dates" type="daterange" value-format="YYYY-MM-DD"/><span class="hint">{{ batchDialog.dates?.join(' 至 ') }}</span></el-form-item><el-form-item label="评审方案(JSON)"><el-input v-model="batchDialog.review" type="textarea" placeholder='例如：{"总分":"成果40+贡献60"}'/></el-form-item><el-form-item label="申报限额"><el-input-number v-model="batchDialog.form.申报限额" :min="1"/></el-form-item><el-form-item label="状态"><el-select v-model="batchDialog.form.状态"><el-option v-for="x in ['草稿','发布','关闭']" :key="x" :label="x" :value="x"/></el-select></el-form-item></el-form><template #footer><el-button @click="batchDialog.visible=false">取消</el-button><el-button type="primary" @click="saveBatch">保存</el-button></template></el-dialog>

    <el-dialog v-model="applicationDialog.visible" title="获奖申报" width="620px"><el-form :model="applicationDialog.form" label-width="105px"><el-form-item label="申报批次"><el-select v-model="applicationDialog.form.批次编号"><el-option v-for="b in batches.filter(x=>x.状态==='发布')" :key="b.编号" :label="b.批次名称" :value="b.编号"/></el-select></el-form-item><el-form-item label="申报名称"><el-input v-model="applicationDialog.form.申报名称"/></el-form-item><el-form-item label="获奖类别"><el-input v-model="applicationDialog.form.获奖类别"/></el-form-item><el-form-item label="拟申报级别"><el-input v-model="applicationDialog.form.拟申报级别"/></el-form-item><el-form-item label="成果摘要"><el-input v-model="applicationDialog.form.成果摘要" type="textarea" :rows="3"/></el-form-item><el-form-item label="关联项目编号"><el-input-number v-model="applicationDialog.form.关联项目编号" :min="1" :controls="false"/></el-form-item></el-form><template #footer><el-button @click="applicationDialog.visible=false">取消</el-button><el-button type="primary" @click="saveApplication">保存</el-button></template></el-dialog>
  </div>
</template>

<script setup lang="ts">
import { onMounted, reactive, ref, watch } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Refresh } from '@element-plus/icons-vue'
import { listAchievementExtensions, listAwardApplications, listAwardBatches, listIntellectualProperties, saveAchievementExtension, saveAwardApplication, saveAwardBatch, saveIntellectualProperty, saveIpEvent, submitAwardApplication, reviewAchievementExtension, type AchievementExtension, type AwardApplication, type AwardBatch, type IntellectualProperty } from '@/api/achievement-ip-awards'

const tab = ref('extensions'); const loading = ref(false); const saving = ref(false)
const loadingExtensions = ref(false); const loadingIp = ref(false); const loadingBatches = ref(false); const loadingApplications = ref(false)
const extensionTypes = ['研究报告','鉴定成果','艺术作品','标准','药品证书','新品种','集成电路布图','其他']; const extensionFilter = ref(''); const extensions = ref<AchievementExtension[]>([])
const ipTypes = ['专利','著作权','标准','药品证书','新品种','集成电路布图']; const ipStates = ['筹备','申请中','受理','审查中','已授权','已登记','已失效','已撤回']; const ipEvents = ['申请','受理','审查','授权','登记','变更','缴费','年费提醒','失效','撤回']; const ipFilter = ref(''); const dueOnly = ref(false); const ips = ref<IntellectualProperty[]>([])
const batches = ref<AwardBatch[]>([]); const applications = ref<AwardApplication[]>([]); const applicationBatch = ref<number | undefined>()
const extensionDialog = reactive<{visible:boolean; form:any; extra:string}>({ visible:false, form:{成果类别:'研究报告',成果名称:'',年度:new Date().getFullYear()}, extra:'{}' })
const ipDialog = reactive<{visible:boolean; form:any}>({ visible:false, form:{知识产权类型:'专利',名称:'',状态:'筹备',总费用:0,已缴费用:0} })
const ipEventDialog = reactive<{visible:boolean; form:any}>({ visible:false, form:{知识产权编号:0,事件类型:'申请',金额:0} })
const batchDialog = reactive<{visible:boolean; form:any; dates:string[]; review:string}>({ visible:false, form:{计划年度:new Date().getFullYear(),批次名称:'',获奖类别:'',状态:'草稿'}, dates:[], review:'{}' })
const applicationDialog = reactive<{visible:boolean; form:any}>({ visible:false, form:{批次编号:undefined,申报名称:''} })
function unwrap<T>(value:any): T[] { return Array.isArray(value) ? value : value?.items || value?.list || value?.List || [] }
function auditType(s?:string){ return s === '已通过' ? 'success' : s === '已退回' ? 'danger' : 'warning' }
function ipStatusType(s?:string){ return ['已授权','已登记'].includes(s || '') ? 'success' : ['已失效','已撤回'].includes(s || '') ? 'info' : 'warning' }
function applicationType(s?:string){ return s === '已认定' ? 'success' : s === '未通过' ? 'danger' : s === '评审中' ? 'warning' : 'info' }
async function loadExtensions(){ loadingExtensions.value=true; try{ extensions.value=unwrap<AchievementExtension>(await listAchievementExtensions(extensionFilter.value?{成果类别:extensionFilter.value}:{})) }catch{extensions.value=[]}finally{loadingExtensions.value=false} }
async function loadIp(){ loadingIp.value=true; try{ ips.value=unwrap<IntellectualProperty>(await listIntellectualProperties({ ...(ipFilter.value?{知识产权类型:ipFilter.value}:{}), 仅待缴费:dueOnly.value })) }catch{ips.value=[]}finally{loadingIp.value=false} }
async function loadBatches(){ loadingBatches.value=true; try{batches.value=unwrap<AwardBatch>(await listAwardBatches())}catch{batches.value=[]}finally{loadingBatches.value=false} }
async function loadApplications(){ loadingApplications.value=true; try{applications.value=unwrap<AwardApplication>(await listAwardApplications(applicationBatch.value?{批次编号:applicationBatch.value}:{ }))}catch{applications.value=[]}finally{loadingApplications.value=false} }
async function refresh(){ loading.value=true; await Promise.allSettled([loadExtensions(),loadIp(),loadBatches(),loadApplications()]); loading.value=false }
async function onTabChange(){ if(tab.value==='extensions') await loadExtensions(); if(tab.value==='ip') await loadIp(); if(tab.value==='batches') await loadBatches(); if(tab.value==='applications') await loadApplications() }
watch(extensionFilter,loadExtensions); watch([ipFilter,dueOnly],loadIp); watch(applicationBatch,loadApplications)
function openExtension(row?:AchievementExtension){ extensionDialog.form=row?{...row}:{成果类别:'研究报告',成果名称:'',年度:new Date().getFullYear()}; extensionDialog.extra=JSON.stringify(row?.扩展字段||{},null,2); extensionDialog.visible=true }
async function saveExtension(){ try{ const 扩展字段=JSON.parse(extensionDialog.extra||'{}'); saving.value=true; await saveAchievementExtension({...extensionDialog.form,扩展字段}); ElMessage.success('成果已保存'); extensionDialog.visible=false; await loadExtensions() }catch(e:any){ if(e instanceof SyntaxError) ElMessage.error('扩展字段必须是有效 JSON') }finally{saving.value=false} }
async function reviewExtension(row:AchievementExtension, 审核状态:'已通过'|'已退回'){ await reviewAchievementExtension({编号:row.编号!,审核状态}); ElMessage.success('审核状态已更新'); await loadExtensions() }
function openIp(row?:IntellectualProperty){ ipDialog.form=row?{...row}:{知识产权类型:'专利',名称:'',状态:'筹备',总费用:0,已缴费用:0}; ipDialog.visible=true }
async function saveIp(){ saving.value=true; try{ await saveIntellectualProperty(ipDialog.form); ElMessage.success('知识产权已保存'); ipDialog.visible=false; await loadIp() }finally{saving.value=false} }
function openIpEvent(row:IntellectualProperty){ ipEventDialog.form={知识产权编号:row.编号,事件类型:'申请',金额:0}; ipEventDialog.visible=true }
async function saveIpEventForm(){ await saveIpEvent(ipEventDialog.form); ElMessage.success('知识产权事件已登记'); ipEventDialog.visible=false; await loadIp() }
function openBatch(row?:AwardBatch){ batchDialog.form=row?{...row}:{计划年度:new Date().getFullYear(),批次名称:'',获奖类别:'',状态:'草稿'}; batchDialog.dates=row?[row.申报开始日期,row.申报截止日期]:[]; batchDialog.review=JSON.stringify(row?.评审方案||{},null,2); batchDialog.visible=true }
async function saveBatch(){ try{ const 评审方案=JSON.parse(batchDialog.review||'{}'); const [申报开始日期,申报截止日期]=batchDialog.dates; await saveAwardBatch({...batchDialog.form,申报开始日期,申报截止日期,评审方案}); ElMessage.success('获奖申报批次已保存'); batchDialog.visible=false; await loadBatches() }catch(e:any){ if(e instanceof SyntaxError) ElMessage.error('评审方案必须是有效 JSON') } }
function openApplication(row?:AwardApplication){ applicationDialog.form=row?{...row}:{批次编号:batches.value.find(x=>x.状态==='发布')?.编号,申报名称:'',获奖类别:'',拟申报级别:''}; applicationDialog.visible=true }
async function saveApplication(){ await saveAwardApplication(applicationDialog.form); ElMessage.success('获奖申报已保存'); applicationDialog.visible=false; await loadApplications() }
async function submitApplication(row:AwardApplication){ await ElMessageBox.confirm('提交后将进入评审队列，确定继续吗？','确认提交'); await submitAwardApplication(row.编号!); ElMessage.success('申报已提交'); await loadApplications() }
async function openReviews(row:AwardApplication){ ElMessage.info(`申报 ${row.申报名称} 的评审记录请使用评审工作台查看`) }
async function openCertify(_row:AwardApplication){ ElMessage.info('请由科研管理角色在获奖认定接口录入证书和认定意见') }
onMounted(refresh)
</script>

<style scoped lang="scss">
.page-container{padding:20px;min-height:100%;background:#f5f7fa}.header-card,.content-card{border:0;border-radius:10px;margin-bottom:16px}.header{display:flex;justify-content:space-between;align-items:center;gap:16px}h2{margin:0 0 8px;color:#1f2937}.header p{margin:0;color:#7b8794}.toolbar{display:flex;gap:10px;align-items:center;margin-bottom:14px;flex-wrap:wrap}.inline-label{margin:0 8px;color:#7b8794}.hint{margin-left:8px;color:#7b8794;font-size:12px}
</style>
